package ru.playsoftware.j2meloader.multiplayer;

import com.google.gson.*;
import org.junit.Test;
import java.util.*;
import java.util.function.Consumer;
import static org.junit.Assert.*;

public class LobbyDirectoryTest {
    @Test public void gameEntryAcceptsUnassignedOrExactEditionAndAdapter(){
        LobbyDirectory.Room choosing=LobbyDirectory.parse(message(value(),0,"900"),LobbyDirectory.CHANNELS.get(0),1000,100);
        assertNotNull(choosing);assertTrue(choosing.acceptsJavaGame("a".repeat(64)));
        JsonObject selected=game(value(),"bluetooth");
        LobbyDirectory.Room match=LobbyDirectory.parse(message(selected,0,"901"),LobbyDirectory.CHANNELS.get(0),1000,100);
        assertNotNull(match);assertTrue(match.acceptsJavaGame("a".repeat(64)));assertFalse(match.acceptsJavaGame("b".repeat(64)));assertFalse(match.acceptsJavaGame(""));
        selected.getAsJsonObject("game").addProperty("adapter","2");
        assertFalse(LobbyDirectory.parse(message(selected,0,"902"),LobbyDirectory.CHANNELS.get(0),1000,100).acceptsJavaGame("a".repeat(64)));
    }
    private static final String ID="00000000-0000-4000-8000-000000000001", TOKEN="fixture-directory-token";
    static JsonObject value(){return JsonParser.parseString("{\"v\":2,\"product\":\"abyssme\",\"protocol\":1,\"lobby\":\""+ID+"\",\"owner\":\"22\",\"name\":\"Test host\",\"revision\":1,\"status\":\"choosing\",\"access\":\"public\",\"seats\":0,\"available\":0,\"streams\":0,\"expires\":1180}").getAsJsonObject();}
    static JsonObject message(JsonObject v,int channel,String id){JsonObject m=new JsonObject();m.addProperty("id",id);m.addProperty("channel_id",LobbyDirectory.CHANNELS.get(channel));JsonObject author=new JsonObject();author.addProperty("id",LobbyDirectory.BOT);m.add("author",author);m.addProperty("content",LobbyDirectory.PREFIX+v+"\n```");return m;}
    static JsonArray page(JsonObject... values){JsonArray a=new JsonArray();for(JsonObject o:values)a.add(o);return a;}
    static JsonObject game(JsonObject v,String mode){v.addProperty("status","gathering");v.addProperty("seats",2);v.addProperty("available",1);JsonObject g=new JsonObject();g.addProperty("id",String.join("",Collections.nCopies(64,"a")));g.addProperty("title","Test game");g.addProperty("platform","j2me");g.addProperty("mode",mode);g.addProperty("adapter","1");v.add("game",g);return v;}
    static final class Request {String method,path;Consumer<FluxerAuth.Reply> callback;Request(String method,String path,Consumer<FluxerAuth.Reply> c){this.method=method;this.path=path;callback=c;}void reply(int code,JsonElement body){callback.accept(new FluxerAuth.Reply(code,body,10000));}}
    static final class Fixture {
        long now=1000,mono=100;List<Request> requests=new ArrayList<>();
        LobbyDirectory d=new LobbyDirectory((method,path,body,token,done)->{if(method.equals("POST")){assertEquals(LobbyDirectory.INVITE_PATH,path);assertEquals(new JsonObject(),body);}else{assertEquals("GET",method);assertNull(body);}requests.add(new Request(method,path,done));},()->now,()->mono,Collections.singleton("j2me/jsr82-l2cap/1"),s->{});
        Request take(){assertFalse(requests.isEmpty());return requests.remove(0);}
        void connect(){d.active(true);d.session(TOKEN);Request r=take();assertEquals("/v1/users/@me",r.path);r.reply(200,JsonParser.parseString("{\"id\":\"11\"}"));}
        void finish(){while(!requests.isEmpty())take().reply(200,new JsonArray());}
        void first(JsonObject v){take().reply(200,page(message(v,0,"900")));finish();}
    }
    @Test public void signedOutDoesNotFetch(){Fixture f=new Fixture();f.d.session(null);f.d.tick();assertTrue(f.requests.isEmpty());assertFalse(f.d.state().verified);}
    @Test public void readsAllChannelsAndShowsGameFreeRoom(){Fixture f=new Fixture();f.connect();f.first(value());assertEquals(1,f.d.state().rooms.size());assertEquals("Choosing a game",f.d.state().rooms.get(0).title);assertFalse(f.d.state().busy);}
    @Test public void rejectsOtherBotAndWebhook(){JsonObject m=message(value(),0,"900");m.getAsJsonObject("author").addProperty("id","33");assertNull(LobbyDirectory.parse(m,LobbyDirectory.CHANNELS.get(0),1000,100));m.getAsJsonObject("author").addProperty("id",LobbyDirectory.BOT);m.addProperty("webhook_id","44");assertNull(LobbyDirectory.parse(m,LobbyDirectory.CHANNELS.get(0),1000,100));}
    @Test public void rejectsWrongChannelOrGuild(){JsonObject m=message(value(),0,"900");assertNull(LobbyDirectory.parse(m,LobbyDirectory.CHANNELS.get(1),1000,100));m.addProperty("guild_id","123");assertNull(LobbyDirectory.parse(m,LobbyDirectory.CHANNELS.get(0),1000,100));}
    @Test public void rejectsLegacyAndOtherProductOrProtocol(){for(String key:Arrays.asList("v","product","protocol")){JsonObject v=value();if(key.equals("product"))v.addProperty(key,"traineros");else v.addProperty(key,key.equals("v")?1:2);assertNull(LobbyDirectory.parse(message(v,0,"900"),LobbyDirectory.CHANNELS.get(0),1000,100));}}
    @Test public void rejectsPrivateAndMalformedFields(){for(String key:Arrays.asList("access","lobby","owner","name")){JsonObject v=value();v.addProperty(key,key.equals("access")?"private":"");assertNull(LobbyDirectory.parse(message(v,0,"900"),LobbyDirectory.CHANNELS.get(0),1000,100));}}
    @Test public void rejectsNonIntegerVersionsAndCounters(){for(String key:Arrays.asList("v","protocol","revision","seats","expires")){JsonObject v=value();v.addProperty(key,1.5);assertNull(LobbyDirectory.parse(message(v,0,"900"),LobbyDirectory.CHANNELS.get(0),1000,100));}}
    @Test public void rejectsHugeFutureExpiryAndExcessSeats(){JsonObject v=value();v.addProperty("expires",1361);assertNull(LobbyDirectory.parse(message(v,0,"900"),LobbyDirectory.CHANNELS.get(0),1000,100));v=game(value(),"jsr82-l2cap");v.addProperty("seats",17);assertNull(LobbyDirectory.parse(message(v,0,"900"),LobbyDirectory.CHANNELS.get(0),1000,100));}
    @Test public void directoryAllowsBoundedServerSkewButKeepsExpiry(){JsonObject v=value();v.addProperty("expires",1322);LobbyDirectory.Room r=LobbyDirectory.parse(message(v,0,"900"),LobbyDirectory.CHANNELS.get(0),1000,100);assertNotNull(r);assertTrue(r.live(1000,100));assertFalse(r.live(1322,322100));}
    @Test public void requiresExactRuntimeModeAdapterNotLocalTitle(){Fixture f=new Fixture();f.connect();f.first(game(value(),"jsr82-l2cap"));assertEquals(1,f.d.state().rooms.size());f.d.refresh();JsonObject v=game(value(),"jsr82-rfcomm");v.addProperty("revision",2);f.first(v);assertTrue(f.d.state().rooms.isEmpty());}
    @Test public void unsupportedNewRevisionCannotRevealOlderSupportedGame(){Fixture f=new Fixture();f.connect();JsonObject newer=game(value(),"unsupported");newer.addProperty("revision",2);f.take().reply(200,page(message(newer,0,"902"),message(game(value(),"jsr82-l2cap"),0,"901")));f.finish();assertTrue(f.d.state().rooms.isEmpty());}
    @Test public void expiredNewRevisionCannotResurrectOlderRoom(){Fixture f=new Fixture();f.connect();JsonObject newer=value();newer.addProperty("revision",2);newer.addProperty("expires",999);f.take().reply(200,page(message(newer,0,"902"),message(value(),0,"901")));f.finish();assertTrue(f.d.state().rooms.isEmpty());}
    @Test public void conflictingOwnersOrSameRevisionAreHidden(){for(boolean owner:new boolean[]{true,false}){Fixture f=new Fixture();f.connect();JsonObject conflict=value();conflict.addProperty(owner?"owner":"name",owner?"33":"Changed");f.take().reply(200,page(message(value(),0,"902"),message(conflict,0,"901")));f.finish();assertTrue(f.d.state().rooms.isEmpty());}}
    @Test public void jsonFieldOrderDoesNotCreateConflict(){Fixture f=new Fixture();f.connect();JsonObject reordered=new JsonObject();List<String> keys=new ArrayList<>(value().keySet());Collections.reverse(keys);for(String key:keys)reordered.add(key,value().get(key));f.take().reply(200,page(message(value(),0,"902"),message(reordered,0,"901")));f.finish();assertEquals(1,f.d.state().rooms.size());}
    @Test public void duplicateAcrossChannelsKeepsHighestRevision(){Fixture f=new Fixture();f.connect();f.take().reply(200,page(message(value(),0,"900")));JsonObject v=value();v.addProperty("revision",2);v.addProperty("name","New name");f.take().reply(200,page(message(v,1,"901")));f.finish();assertEquals(1,f.d.state().rooms.size());assertEquals("New name",f.d.state().rooms.get(0).name);}
    @Test public void expiryUsesMonotonicTimeEvenAfterClockMovesBack(){Fixture f=new Fixture();f.connect();f.first(value());f.now=900;f.mono+=181000;f.d.tick();assertTrue(f.d.state().rooms.isEmpty());f.first(value());assertTrue(f.d.state().rooms.isEmpty());}
    @Test public void shortPageMovesToNextChannel(){Fixture f=new Fixture();f.connect();f.take().reply(200,new JsonArray());assertTrue(f.requests.get(0).path.contains(LobbyDirectory.CHANNELS.get(1)));f.finish();}
    @Test public void fullPageUsesBeforeCursor(){Fixture f=new Fixture();f.connect();JsonArray p=new JsonArray();for(int i=100;i>50;i--){JsonObject m=message(value(),0,Integer.toString(i));m.getAsJsonObject("author").addProperty("id","99");p.add(m);}f.take().reply(200,p);assertTrue(f.requests.get(0).path.endsWith("&before=51"));f.finish();assertTrue(f.d.state().rooms.isEmpty());}
    @Test public void repeatedOrWrongChannelPageFailsClosed(){for(boolean wrongChannel:new boolean[]{true,false}){Fixture f=new Fixture();f.connect();JsonArray p=wrongChannel?page(message(value(),1,"900")):page(message(value(),0,"900"),message(value(),0,"900"));f.take().reply(200,p);assertTrue(f.d.state().rooms.isEmpty());assertFalse(f.d.state().busy);assertTrue(f.requests.isEmpty());}}
    @Test public void failedInviteCheckDoesNotPostOrLoop(){Fixture f=new Fixture();f.connect();f.take().reply(403,null);Request invite=f.take();assertEquals("GET",invite.method);assertEquals(LobbyDirectory.INVITE_PATH,invite.path);invite.reply(404,null);assertTrue(f.d.state().needsCommunity);f.mono+=60000;f.d.tick();assertTrue(f.requests.isEmpty());}
    @Test public void errorsClearPreviouslyVisibleRooms(){Fixture f=new Fixture();f.connect();f.first(value());f.d.refresh();f.take().reply(500,null);assertTrue(f.d.state().rooms.isEmpty());assertFalse(f.d.state().busy);}
    @Test public void expiredSessionClearsAccountAndDirectory(){Fixture f=new Fixture();f.connect();f.first(value());f.d.refresh();f.take().reply(401,null);assertFalse(f.d.state().verified);assertEquals("",f.d.state().account);assertTrue(f.d.state().rooms.isEmpty());}
    @Test public void rateLimitPreventsRefreshIncludingResume(){Fixture f=new Fixture();f.connect();f.take().reply(429,null);f.d.session(TOKEN);f.d.refresh();f.d.tick();assertTrue(f.requests.isEmpty());f.mono+=10001;f.d.refresh();assertEquals(1,f.requests.size());}
    @Test public void accountChangeDiscardsLatePages(){Fixture f=new Fixture();f.connect();Request old=f.take();f.d.session(null);old.reply(200,page(message(value(),0,"900")));assertTrue(f.d.state().rooms.isEmpty());assertFalse(f.d.state().verified);assertTrue(f.requests.isEmpty());}
    @Test public void pauseAndCloseFenceRequests(){Fixture f=new Fixture();f.connect();Request old=f.take();f.d.active(false);old.reply(200,page(message(value(),0,"900")));assertTrue(f.d.state().rooms.isEmpty());f.mono+=60000;f.d.tick();assertTrue(f.requests.isEmpty());f.d.active(true);f.d.refresh();old=f.take();f.d.close();old.reply(200,new JsonArray());assertTrue(f.requests.isEmpty());}
    @Test public void anonymousAuthRateLimitCannotBeBypassed(){Fixture f=new Fixture();f.d.session(TOKEN);f.take().reply(429,null);f.d.session(TOKEN);assertTrue(f.requests.isEmpty());}
    @Test public void noRuntimeCapabilityMeansOnlyGameFreeRooms(){List<LobbyDirectory.State> events=new ArrayList<>();final int[] n={0};LobbyDirectory d=new LobbyDirectory((method,path,body,token,done)->{JsonElement reply;if(path.equals("/v1/users/@me"))reply=JsonParser.parseString("{\"id\":\"11\"}");else{int channel=n[0]++;reply=channel==0?page(message(game(value(),"jsr82-l2cap"),0,"900")):new JsonArray();}done.accept(new FluxerAuth.Reply(200,reply,0));},()->1000,()->100,Collections.emptySet(),events::add);d.session(TOKEN);assertTrue(d.state().rooms.isEmpty());}
    static JsonObject invite(){return JsonParser.parseString("{\"code\":\"kOYY3hzY\",\"type\":0,\"guild\":{\"id\":\""+LobbyDirectory.GUILD+"\"}}").getAsJsonObject();}
    @Test public void autoJoinVerifiesInviteThenRefreshesWithoutUserAction(){Fixture f=new Fixture();f.connect();f.take().reply(403,null);f.take().reply(200,invite());Request post=f.take();assertEquals("POST",post.method);post.reply(200,invite());f.first(value());assertEquals(1,f.d.state().rooms.size());assertFalse(f.d.state().needsCommunity);}
    @Test public void wrongCommunityInviteNeverTriggersMembershipWrite(){Fixture f=new Fixture();f.connect();f.take().reply(403,null);JsonObject wrong=invite();wrong.getAsJsonObject("guild").addProperty("id","44");f.take().reply(200,wrong);assertTrue(f.requests.isEmpty());assertTrue(f.d.state().needsCommunity);}
    @Test public void wrongInviteTypeOrCodeCannotJoin(){for(String field:Arrays.asList("type","code")){Fixture f=new Fixture();f.connect();f.take().reply(403,null);JsonObject wrong=invite();if(field.equals("type"))wrong.addProperty(field,1);else wrong.addProperty(field,"other");f.take().reply(200,wrong);assertTrue(f.requests.isEmpty());}}
    @Test public void lostJoinReplyReconcilesReadOnly(){Fixture f=new Fixture();f.connect();f.take().reply(403,null);f.take().reply(200,invite());f.take().reply(0,null);Request check=f.take();assertEquals("GET",check.method);check.reply(403,null);assertTrue(f.d.state().needsCommunity);assertTrue(f.requests.isEmpty());f.d.refresh();f.take().reply(403,null);assertTrue(f.requests.isEmpty());}
    @Test public void explicitRetryIsAccountBoundAndRechecksInvite(){Fixture f=new Fixture();f.connect();f.take().reply(403,null);f.take().reply(200,invite());f.take().reply(403,null);f.d.retryCommunity("22");assertTrue(f.requests.isEmpty());f.d.retryCommunity("11");Request retry=f.take();assertEquals("GET",retry.method);assertEquals(LobbyDirectory.INVITE_PATH,retry.path);retry.reply(200,invite());assertEquals("POST",f.take().method);}
    @Test public void accountChangeFencesLateInviteAndJoin(){for(boolean afterPost:new boolean[]{true,false}){Fixture f=new Fixture();f.connect();f.take().reply(403,null);Request pending=f.take();if(afterPost){pending.reply(200,invite());pending=f.take();}f.d.session(null);pending.reply(200,invite());assertTrue(f.requests.isEmpty());assertFalse(f.d.state().verified);}}
    @Test public void membershipFailureDoesNotRepeatAfterNewSessionForSameAccount(){Fixture f=new Fixture();f.connect();f.take().reply(403,null);f.take().reply(200,invite());f.take().reply(403,null);f.d.session(null);f.connect();f.take().reply(403,null);assertTrue(f.requests.isEmpty());assertTrue(f.d.state().needsCommunity);}
    @Test public void joinRateLimitUnlocksExplicitRetryAfterDelay(){Fixture f=new Fixture();f.connect();f.take().reply(403,null);f.take().reply(200,invite());f.take().reply(429,null);f.d.retryCommunity("11");assertTrue(f.requests.isEmpty());f.mono+=10001;f.d.tick();assertEquals(0,f.d.state().retryAt);assertTrue(f.requests.isEmpty());f.d.retryCommunity("11");assertEquals(LobbyDirectory.INVITE_PATH,f.take().path);}
    @Test public void markerWriteFailurePreventsAutomaticJoin(){List<Request> requests=new ArrayList<>();LobbyDirectory d=new LobbyDirectory((method,path,body,token,done)->requests.add(new Request(method,path,done)),()->1000,()->100,Collections.emptySet(),s->{},account->{throw new java.io.IOException();});d.session(TOKEN);requests.remove(0).reply(200,JsonParser.parseString("{\"id\":\"11\"}"));requests.remove(0).reply(403,null);assertTrue(requests.isEmpty());assertTrue(d.state().needsCommunity);d.retryCommunity("11");assertTrue(requests.isEmpty());}
}
